def analyze(component):
    if is_literal(component):
        return analyze_literal(component)
    elif is_name(component):
        return analyze_name(component)
    elif is_application(component):
        return analyze_application(component)
    elif is_operator_combination(component):
        return analyze(operator_combination_to_application(component))
    elif is_conditional(component):
        return analyze_conditional(component)
    elif is_lambda_expression(component):
        return analyze_lambda_expression(component)
    elif is_sequence(component):
        return analyze_sequence(sequence_statements(component))
    elif is_return_statement(component):
        return analyze_return_statement(component)
    elif is_function_definition(component):
        return analyze_function_definition(component)
    elif (is_pass_statement(component) or
          is_global_statement(component) or
          is_nonlocal_statement(component)):
        return lambda env: None
    elif is_assignment(component):
        return analyze_assignment(component)
    else:
        return error('unknown syntax -- analyze', component)

