def analyze_application(component):
    ffun = analyze(function_expression(component))
    afuns = map(analyze, arg_expressions(component))
    return lambda env: execute_application(ffun(env),
                                           map(lambda afun: afun(env), afuns))
def execute_application(fun, args):
    if is_built_in_function(fun):
        return apply_built_in_function(fun, args)
    elif is_compound_function(fun):
        env = extend_environment(function_parameters(fun),
                                 args,
                                 function_environment(fun))
        result = function_body(fun)(env)
        if is_return_value(result):
            return return_value_content(result)
        else:
            return None
    else:
        return error('unknown function type -- execute_application', fun)

